import { ParentBridgeConfig } from '../model/bridge-config';
import BaseBridge from '../base-bridge';

export default class ParentBridge extends BaseBridge {
  iframe: HTMLIFrameElement;

  onChildMessage = (event: MessageEvent) => {
    if (this.config.origin && this.config.origin !== '*' && event.origin !== this.config.origin) {
      return;
    }
    if (event.source !== this.iframe.contentWindow) {
      return;
    }
    const data = event.data as Record<string, any> | undefined;
    if (data) {
      this.onReceiveMessage(data);
    }
  };
  constructor(iframe: HTMLIFrameElement, config: ParentBridgeConfig) {
    super(config);
    this.iframe = iframe;

    window.addEventListener('message', this.onChildMessage);
  }

  sendJsonMessage(message: Record<string, any>): void {
    this.iframe.contentWindow?.postMessage(message, (this.config as ParentBridgeConfig).origin);
  }

  dispose(): void {
    window.removeEventListener('message', this.onChildMessage);
  }
}
