import { BridgeConfig, ParentType } from '../model/bridge-config';
import BaseBridge from '../base-bridge';
import { safeJsonParse } from '../util/safe-json-parse';

export default class ChildBridge extends BaseBridge {
  constructor(config: BridgeConfig) {
    super(config);
    if (this.parentType === 'web') {
      window.addEventListener(
        'message',
        (event: MessageEvent) => {
          if (
            this.config.origin &&
            this.config.origin !== '*' &&
            event.origin !== this.config.origin
          ) {
            return;
          }
          if (event.source !== window.parent) {
            return;
          }
          const data = event.data as Record<string, any> | undefined;
          if (data) {
            this.onReceiveMessage(data);
          }
        },
        false,
      );
    } else if (this.config.native) {
      const { ios, android } = this.config.native;
      if (this.parentType === 'ios') {
        (window as Record<string, any>)[ios!.bridgeName + 'Receiver'] = (
          data: string | Record<string, any>,
        ) => {
          if (typeof data === 'string') {
            const json = safeJsonParse(data);
            if (json) {
              this.onReceiveMessage(json);
            }
          } else {
            this.onReceiveMessage(data);
          }
        };
      } else if (this.parentType === 'android') {
        (window as Record<string, any>)[android!.bridgeName + 'Receiver'] = (
          data: string | Record<string, any>,
        ) => {
          if (typeof data === 'string') {
            const json = safeJsonParse(data);
            if (json) {
              this.onReceiveMessage(json);
            }
          } else {
            this.onReceiveMessage(data);
          }
        };
      }
    }
  }

  override sendJsonMessage(message: Record<string, any>): void {
    if (this.parentType === 'web' && window.parent && window.parent !== window) {
      window.parent.postMessage(message, this.config.origin ?? '*');
    } else if (this.config.native) {
      const { ios, android } = this.config.native;
      if (this.parentType === 'ios') {
        (window as any).webkit.messageHandlers[ios!.bridgeName].postMessage(message);
      } else if (this.parentType === 'android') {
        (window as any)[android!.bridgeName].onIncomingBridgeMessage(JSON.stringify(message));
      }
    }
  }

  public get parentType(): ParentType {
    if (window.parent && window.parent !== window) {
      return 'web';
    }
    if (this.config.native) {
      const { ios, android } = this.config.native;
      if (
        ios?.bridgeName &&
        (window as any).webkit &&
        (window as any).webkit.messageHandlers &&
        (window as any).webkit.messageHandlers[ios.bridgeName]
      ) {
        return 'ios';
      } else if (android?.bridgeName && (window as any)[android.bridgeName]) {
        return 'android';
      }
    }
    return 'unknown';
  }
}
